/* Base Reset & Fonts */
* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    background-color: #1e1e2e;
    color: #cdd6f4;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
}

.container {
    text-align: center;
    background: #313244;
    padding: 2rem;
    border-radius: 16px;
    box-shadow: 0 10px 25px rgba(0,0,0,0.3);
    max-width: 400px;
    width: 90%;
}

header h1 {
    font-size: 2.5rem;
    margin-bottom: 0.5rem;
    color: #fab387;
}

header p {
    color: #a6adc8;
    margin-bottom: 2rem;
}

/* Board Layout */
.board {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 10px;
    margin: 0 auto;
    width: fit-content;
}

.cell {
    width: 80px;
    height: 80px;
    background-color: #45475a;
    border: none;
    border-radius: 8px;
    font-size: 2.5rem;
    font-weight: bold;
    color: #cdd6f4;
    cursor: pointer;
    transition: background-color 0.2s, transform 0.1s;
    display: flex;
    justify-content: center;
    align-items: center;
}

.cell:hover:not([disabled]) {
    background-color: #585b70;
    transform: translateY(-2px);
}

.cell:active:not([disabled]) {
    transform: translateY(0);
}

.cell[disabled] {
    cursor: default;
    opacity: 0.9;
}

/* Player Colors */
.cell-x {
    color: #89b4fa; /* Blue */
}

.cell-o {
    color: #f38ba8; /* Red */
}

/* Status Bar */
.status-bar {
    margin-bottom: 1.5rem;
    font-size: 1.25rem;
    font-weight: 600;
}

.winner-announcement {
    color: #a6e3a1; /* Green */
    animation: popIn 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

/* Reset Button */
.btn {
    display: inline-block;
    margin-top: 10px;
    padding: 10px 20px;
    background-color: #cba6f7;
    color: #1e1e2e;
    border: none;
    border-radius: 8px;
    font-weight: bold;
    cursor: pointer;
    transition: background-color 0.2s;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.btn:hover {
    background-color: #dce0e8;
}

.instructions {
    margin-top: 2rem;
    font-size: 0.9rem;
    color: #6c7086;
}

/* Animations */
@keyframes popIn {
    0% { transform: scale(0.8); opacity: 0; }
    100% { transform: scale(1); opacity: 1; }
}

.fade-in {
    animation: fadeIn 0.3s ease-in;
}

@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

